function forestIntro(){const wait=forestPhase==='loading',moving=['opening','walk','sit'].includes(forestPhase);return `<main class="forest-intro">${forestLook()}${wait?btn(ambience.playing?'♫ 숲 소리 재생 중':'♫ 눌러서 숲 소리 듣기','loading-sound','loading-sound',ambience.playing?'disabled':''):''}<details class="forest-settings"><summary aria-label="숲 설정">☰ 숲 설정</summary><div class="forest-settings-panel">${mapChoice()}${qualityChoice()}<label class="forest-sound-choice"><input type="checkbox" id="forest-sound" ${forestSound?'checked':''}> 숲 배경음</label>${forestPhase==='arrive'?avatarChoice():''}<div class="forest-actions">${wait||moving?'':btn('피아노로 자동 이동','forest-walk','outlined')}${btn('바로 작곡하기','forest-skip','outlined')}</div></div></details><p class="forest-status ${wait?'':'sr-only'}" role="status">${wait?'숲길을 준비하고 있어요…':forestPhase==='opening'?'숲을 둘러보고 있어요…':moving?'피아노에 앉고 있어요.':'방향키로 피아노 가까이 가면 작곡이 시작돼요. 화면을 드래그해 둘러보세요.'}</p>${forestPhase==='arrive'?`<div class="forest-start-card"><strong>${forestMapName(forestMap)}</strong><span>숲을 둘러보거나, 바로 내 노래를 만들어요.</span>${btn(!isEmptySong(song)?'♪ 이어서 작곡하기':'♪ 작곡 시작하기','forest-compose','primary')}${!isEmptySong(song)?`<small>${esc(song.title)} · ${forestMapName(songForestMap(song))}</small>${btn('새 크리스마스 곡','new-christmas','outlined')}`:''}</div><div class="forest-movement" role="group" aria-label="숲에서 이동"><span>방향키 · WASD</span>${[['up','↑','앞으로'],['left','←','왼쪽으로'],['down','↓','뒤로'],['right','→','오른쪽으로']].map(([id,icon,label])=>`<button type="button" data-move="${id}" class="move-${id}" aria-label="${label} 걷기">${icon}</button>`).join('')}</div>`:''}</main>`;}
