function askNewSong(id=song.progression,map=forestMap){if(document.querySelector('dialog.ask'))return;if(isEmptySong(song)){startSong(id,map);return;}stop();render();const d=document.createElement('dialog'),back=()=>app.querySelector('[data-action="new"]')?.focus();let busy=false;d.className='dialog ask';d.setAttribute('aria-labelledby','ask-text');d.innerHTML='<p id="ask-text">'+'새 악보로 시작합니다. 지금 작품을 먼저 보관할까요?'+'</p><div class="dialog-actions"><button type="button" class="primary" value="save">저장 후 시작</button><button type="button" class="outlined" value="skip">저장하지 않고 시작</button><button type="button" class="quiet" value="cancel">취소</button></div>';const close=()=>{busy=false;d.close();d.remove();};d.oncancel=e=>{e.preventDefault();if(!busy){close();back();}};d.onclose=()=>{if(busy)d.showModal();};d.onclick=e=>{const v=e.target.closest?.('button')?.value;if(busy||!v)return;if(v==='cancel'){close();back();}else if(v==='skip'){close();startSong(id,map);}else{busy=true;d.querySelectorAll('button').forEach(b=>b.disabled=true);const snap=clone(song);withLibraryLock(()=>keepSong(localStorage,snap)).then(r=>{close();startSong(id,map);toast(r.duplicate?'이미 보관한 작품이에요.':'작품을 보관했어요.');},err=>{close();toast(err.message);back();});}};document.body.append(d);d.showModal();d.querySelector('button').focus();}

