 const reset=()=>{held.clear();touches.clear();drag=null;app.querySelectorAll('[data-move]').forEach(b=>b.classList.remove('held'));forest?.resetControls();};
 const editable=e=>e.target.closest?.('input,textarea,select,[contenteditable="true"],dialog');
 document.addEventListener('keydown',e=>{const k=keys[e.code];if(document.querySelector('.entrance-overlay')||forestPhase!=='arrive'||!k||editable(e)||e.ctrlKey||e.metaKey||e.altKey)return;e.preventDefault();held.set(e.code,k);send();},{signal});
